#[test]
fn existing_funnel_configuration_blocks_publication_without_invoking_funnel() {
    let serve = r#"{\"Web\":{\"my-pc.example-tailnet.ts.net:443\":{\"Handlers\":{\"/\":{\"Proxy\":\"http://127.0.0.1:9000\"}}}},\"AllowFunnel\":{\"my-pc.example-tailnet.ts.net:443\":true}}"#;
    let cli = FakeCli::new(vec![running_status(), FakeCli::ok(serve)]);
    assert!(matches!(
        reconcile_tailscale(&cli, "http://127.0.0.1:59368", None),
        Err(TailscalePublicationError::ExistingConfigurationConflict)
    ));
    assert_eq!(cli.calls().len(), 2);
    assert_eq!(cli.calls()[1], vec!["serve", "status", "--json"]);
    assert!(
        cli.calls()
            .iter()
            .all(|call| call.first().is_none_or(|argument| argument != "funnel"))
    );
}
